import SchemaBuilder from '@pothos/core';
import { type Giraffe as GiraffeModel, giraffes } from './models/giraffe';

const builder = new SchemaBuilder({});

const Giraffe = builder.objectRef<GiraffeModel>('Giraffe');
Giraffe.implement({
  fields: (t) => ({
    name: t.exposeString('name', { nullable: false }),
    height: t.exposeFloat('height', { nullable: false }),
  }),
});

builder.queryType({
  fields: (t) => ({
    giraffes: t.field({
      type: [Giraffe],
      nullable: false,
      args: { minimumHeight: t.arg.float({ required: true }) },
      resolve: (_parent, args) =>
        giraffes.filter((giraffe) => giraffe.height >= args.minimumHeight),
    }),
  }),
});

export const schema = builder.toSchema();

export interface Giraffe {
  name: string;
  height: number;
}

export const giraffes: Giraffe[] = [
  { name: 'James', height: 5.2 },
  { name: 'Lucy', height: 4.3 },
];

defaultQuery:
query Visit($minimumHeight: Float!) {
  giraffes(minimumHeight: $minimumHeight) {
    name
    height
  }
}

